 function: {name: string , parameters: {}, description: string , strict: true} } ] }) }; fetch( https://api.moonshot.cn/v1/chat/completions , options) .then(res = res.json()) .then(res = console.log(res)) .catch(err = console.error(err)); ?php $curl = curl_init(); curl_setopt_array($curl, [ CURLOPT_URL = https://api.moonshot.cn/v1/chat/completions , CURLOPT_RETURNTRANSFER = true, CURLOPT_ENCODING = , CURLOPT_MAXREDIRS = 10, CURLOPT_TIMEOUT = 30, CURLOPT_HTTP_VERSION = CURL_HTTP_VERSION_1_1, CURLOPT_CUSTOMREQUEST = POST , CURLOPT_POSTFIELDS = json_encode([ messages = [ [ role = user , content = 你好 , name = null, partial = false ] ], model = kimi-k3.1-pro , tools = [ [ type = function , function = [ name = string , parameters = [ ], description = string , strict = true ] ] ] ]), CURLOPT_HTTPHEADER = [ Authorization: Bearer token , Content-Type: application/json ], ]); $response = curl_exec($curl); $err = curl_error($curl); curl_close($curl); if ($err) { echo cURL Error #: . $err; } else { echo $response; } package main import ( fmt strings net/http io ) func main() { url := https://api.moonshot.cn/v1/chat/completions payload := strings.NewReader( {
 \ messages\ : [
 {
 \ role\ : \ user\ ,
 \ content\ : \ 你好\ ,
 \ name\ : null,
 \ partial\ : false
 }
 ],
 \ model\ : \ kimi-k3.1-pro\ ,
 \ tools\ : [
 {
 \ type\ : \ function\ ,
 \ function\ : {
 \ name\ : \ string \ ,
 \ parameters\ : {},
 \ description\ : \ string \ ,
 \ strict\ : true
 }
 }
 ]
} ) req, _ := http.NewRequest( POST , url, payload) req.Header.Add( Authorization , Bearer token ) req.Header.Add( Content-Type , application/json ) res, _ := http.DefaultClient.Do(req) defer res.Body.Close() body, _ := io.ReadAll(res.Body) fmt.Println(string(body)) } HttpResponse String response = Unirest.post( https://api.moonshot.cn/v1/chat/completions ) .header( Authorization , Bearer token ) .header( Content-Type , application/json ) .body( {
 \ messages\ : [
 {
 \ role\ : \ user\ ,
 \ content\ : \ 你好\ ,
 \ name\ : null,
 \ partial\ : false
 }
 ],
 \ model\ : \ kimi-k3.1-pro\ ,
 \ tools\ : [
 {
 \ type\ : \ function\ ,
 \ function\ : {
 \ name\ : \ string \ ,
 \ parameters\ : {},
 \ description\ : \ string \ ,
 \ strict\ : true
 }
 }
 ]
} ) .asString(); require uri require net/http url = URI( https://api.moonshot.cn/v1/chat/completions ) http = Net::HTTP.new(url.host, url.port) http.use_ssl = true request = Net::HTTP::Post.new(url) request[ Authorization ] = Bearer token request[ Content-Type ] = application/json request.body = {
 \ messages\ : [
 {
 \ role\ : \ user\ ,
 \ content\ : \ 你好\ ,
 \ name\ : null,
 \ partial\ : false
 }
 ],
 \ model\ : \ kimi-k3.1-pro\ ,
 \ tools\ : [
 {
 \ type\ : \ function\ ,
 \ function\ : {
 \ name\ : \ string \ ,
 \ parameters\ : {},
 \ description\ : \ string \ ,
 \ strict\ : true
 }
 }
 ]
} response = http.request(request) puts response.read_body 200 400 401 500 { id : string , object : chat.completion , created : 123, model : string , choices : [ { index : 123, message : { role : assistant , content : string , tool_calls : [ { id : string , type : function , function : { name : string , arguments : string } } ], reasoning_content : string }, finish_reason : stop } ], usage : { prompt_tokens : 123, completion_tokens : 123, total_tokens : 123, cached_tokens : 123, prompt_tokens_details : { cached_tokens : 123, cache_write_tokens : 123 } } } { error : { message : string , type : string , code : string } } { error : { message : string , type : string , code : string } } { error : { message : string , type : string , code : string } } 创建一个对话补全请求，模型将根据输入的消息列表生成回复。 Content 字段说明 content 字段支持以下两种形式： 纯文本字符串 { content : 你好 } 对象数组 （用于多模态输入） 数组中每个元素通过 type 字段区分类型： { content : [ { type : text , text : 描述这张图片 }, { type : image_url , image_url : { url : data:image/png;base64,... } }, { type : video_url , video_url : { url : data:video/mp4;base64,... } } ] } 其中 image_url 和 video_url 也支持直接传入字符串，效果等同于对象形式中的 url 字段： { type : image_url , image_url : data:image/png;base64,... } 参数说明 数组中每个元素的字段说明如下： 参数名称 是否必须 说明 类型 type required 内容类型 text | image_url | video_url text 当 type=text 时必填 文本内容 string image_url 当 type=image_url 时必填 用于传输图片，支持对象形式 { url : ... } 或直接传入 URL 字符串 object | string video_url 当 type=video_url 时必填 用于传输视频，支持对象形式 { url : ... } 或直接传入 URL 字符串 object | string 当 image_url 传入对象时，其字段说明如下： 参数名称 是否必须 说明 类型 url required 使用 base64 编码或通过 file id 指定的图片内容 string 当 video_url 传入对象时，其字段说明如下： 参数名称 是否必须 说明 类型 url required 使用 base64 编码或通过 file id 指定的视频内容，例如 data:video/mp4;base64,... string 无论使用对象形式（ url 字段）还是字符串简写，均支持以下两种格式： base64 编码： data:image/png;base64,... 或 data:video/mp4;base64,... 文件引用： ms:// file_id 详见 使用 Kimi 视觉模型 。 调用示例 python curl node.js import os import base64 from openai import OpenAI from openai.types.chat import ChatCompletion client: OpenAI = OpenAI( api_key = os.environ.get( MOONSHOT_API_KEY ), base_url = https://api.moonshot.cn/v1 , ) # 对图片进行 base64 编码 with open ( 您的图片地址 , rb ) as f: img_base: str = base64.b64encode(f.read()).decode( utf-8 ) response: ChatCompletion = client.chat.completions.create( model = kimi-k3.1-pro , messages = [ { role : user , content : [ { type : image_url , image_url : { url : f data:image/jpeg;base64, { img_base } , }, }, { type : text , text : 请描述这个图片 , }, ], } ], ) print (response.choices[ 0 ].message.content) See all 36 lines curl https://api.moonshot.cn/v1/chat/completions \ -H Content-Type: application/json \ -H Authorization: Bearer $MOONSHOT_API_KEY \ -d { model : kimi-k3.1-pro , messages : [ { role : user , content : [ { type : image_url , image_url : { url : data:image/jpeg;base64,/9j/4AAQ... } }, { type : text , text : 请描述这个图片 } ] } ] } const fs = require ( fs ); const OpenAI = require ( openai ); const client = new OpenAI ({ apiKey: process . env . MOONSHOT_API_KEY , baseURL: https://api.moonshot.cn/v1 , }); async function main () { // 对图片进行 base64 编码 const imgBase = fs . readFileSync ( 您的图片地址 ). toString ( base64 ); const response = await client . chat . completions . create ({ model: kimi-k3.1-pro , messages: [ { role: user , content: [ { type: image_url , image_url: { url: `data:image/jpeg;base64, ${ imgBase } ` , }, }, { type: text , text: 请描述这个图片 , }, ], }, ], }); console . log ( response . choices [ 0 ]. message . content ); } main (); 响应格式 非流式响应 { id : chatcmpl-6adb0d416a4a9c1d0fe639e3 , object : chat.completion , created : 1792740676 , model : kimi-k3.1-pro , choices : [ { index : 0 , message : { content : 1 + 1 = 2 , role : assistant , reasoning_content : The user is asking a simple math question in Chinese: \ 1+1 等于多少？ \ (What is 1+1?) 

 This is a trivial arithmetic question. The answer is 2. I should respond in Chinese since the conversation is in Chinese. Keep it simple and direct. }, finish_reason : stop } ], usage : { completion_tokens : 82 , prompt_tokens : 309 , total_tokens : 391 , completion_tokens_details : { reasoning_tokens : 60 }, prompt_tokens_details : { cache_write_tokens : 256 } } } 流式响应 设置 stream=true 和 stream_options.include_usage=true ；先返回 reasoning_content ，再返回 content ，最后的统计块为 choices: [] ，总用量位于顶层 usage 。 data: { id : chatcmpl-6adb0ef5ba679679914a2719 , object : chat.completion.chunk , created :1792741109, model : kimi-k3.1-pro , choices :[{ index :0, delta :{ role : assistant , content : }, finish_reason :null}], system_fingerprint : fpv0_dd3f7976 } data: { id : chatcmpl-6adb0ef5ba679679914a2719 , object : chat.completion.chunk , created :1792741109, model : kimi-k3.1-pro , choices :[{ index :0, delta :{ reasoning_content : The }, finish_reason :null}], system_fingerprint : fpv0_dd3f7976 } ... data: { id : chatcmpl-6adb0ef5ba679679914a2719 , object : chat.completion.chunk , created :1792741109, model : kimi-k3.1-pro , choices :[{ index :0, delta :{ content : 1 }, finish_reason :null}], system_fingerprint : fpv0_dd3f7976 } ... data: { id : chatcmpl-6adb0ef5ba679679914a2719 , object : chat.completion.chunk , created :1792741109, model : kimi-k3.1-pro , choices :[], usage :{ prompt_tokens :309, completion_tokens :101, total_tokens :410, completion_tokens_details :{ reasoning_tokens :71}, prompt_tokens_details :{ cache_write_tokens :256}}} data: [DONE] 响应示例中的模型名称会根据请求中的 model 参数返回。当使用 kimi-k3.1-pro 模型时，响应中的 model 字段将显示为 kimi-k3.1-pro 。 上下文缓存（Cache Write） Cache Write 适用于 kimi-k3.1-pro 、 kimi-k3.1-pro-highspeed 和 kimi-k3 。Kimi API 会对重复的请求前缀自动启用上下文缓存，命中部分以更低价格计费且响应更快。通过 prompt_cache_options 可以控制缓存写入行为： 参数 类型 说明 prompt_cache_options object 上下文缓存写入选项。不传时默认开启缓存写入（ 5m 档） prompt_cache_options.mode implicit 缓存写入模式，仅支持 implicit ：自动将请求前缀写入缓存 prompt_cache_options.ttl 5m | 1h 缓存写入的有效期，仅支持 5m 、 1h 两档（默认 5m ），两档缓存相互独立 { model : kimi-k3.1-pro , messages : [{ role : user , content : 你好 }], prompt_cache_options : { mode : implicit , ttl : 1h } } 行为说明 缓存以组织（org）为粒度隔离，组织之间不共享缓存。 相同前缀的请求在缓存有效期内命中后，缓存的有效期会按原 TTL 刷新；命中部分只收取缓存读取费用，不再收取缓存写入费用。 缓存写入按 TTL 分别计费，价格详见 产品定价 。 不支持手动清除缓存，已缓存的前缀在至少 5 分钟不活动后自动过期。 暂不支持显式缓存断点： content 中出现 prompt_cache_breakpoint 时请求会被拒绝（HTTP 400）。 用量字段 usage.prompt_tokens 始终为总输入 Token 数，其内部分类通过 prompt_tokens_details 返回： 字段 说明 usage.prompt_tokens_details.cached_tokens 命中缓存的 Token 数量（缓存读取） usage.prompt_tokens_details.cache_write_tokens 本次写入缓存的 Token 数量（缓存写入） cached_tokens 、 cache_write_tokens 与未缓存部分互斥，三者之和等于 prompt_tokens ，即未缓存部分 = prompt_tokens − cached_tokens − cache_write_tokens 。 上方非流式响应中，输入为 309 Token，其中缓存写入 256 Token；输出为 82 Token，总计 309 + 82 = 391 Token。缓存读写已包含在 prompt_tokens 中，输出包含推理与正文，不应重复累加。 流式请求中，完整的缓存读写明细仅在最后一个 chunk 的 usage 字段中返回（需设置 stream_options.include_usage=true ）。Chat Completions 的响应不回显实际应用的 mode/ttl（与 Responses API 不同），请从请求发起侧记录所用取值。 Context Caching 的机制背景详见 上下文缓存指南 。 多轮对话 Kimi API 是无状态的，本身不具有记忆功能。要实现多轮对话，需在每次请求时把前一轮的 assistant 回复（以及工具执行结果，如适用）原样追加到 messages 数组中再发送。 messages = [ { role : system , content : 你是 Kimi。 }, { role : user , content : 你好，我叫李雷。 } ] completion = client.chat.completions.create( model = kimi-k3.1-pro , messages = messages) reply = completion.choices[ 0 ].message # 原样保留完整 assistant 回复，包括 reasoning_content 和可能的 tool_calls messages.append(reply.model_dump( exclude_none = True )) messages.append({ role : user , content : 1+1 等于多少？ }) completion = client.chat.completions.create( model = kimi-k3.1-pro , messages = messages) print (completion.choices[ 0 ].message.content) 当对话历史过长时，建议只保留最近的若干条消息，或做消息压缩，以避免超出模型的上下文长度限制。 详见 配置多轮对话参数 。 JSON Mode 通过 response_format 参数可约束模型输出格式： { type : text } （默认）：普通文本输出 { type : json_object } ：强制输出合法 JSON Object { type : json_schema , json_schema : {...}} ：按给定 JSON Schema 输出结构化数据（Structured Output） 使用 json_object 时， 必须在 system prompt 或 user prompt 中明确描述期望的 JSON 字段和类型 ，否则模型可能输出不符合预期的结果。 { model : kimi-k3.1-pro , messages : [ { role : system , content : 请输出 JSON，包含 title、author、summary 字段。 }, { role : user , content : 总结这篇文章：递归通过把问题分解为更小的同类子问题来求解，并通过终止条件结束调用。 } ], response_format : { type : json_object } } 详见 使用 Kimi API 的 JSON Mode 。 工具调用 Tool Use 通过 tools 参数传入 JSON Schema 定义的外部工具，模型可决定在适当时机调用它们。 请求示例 { model : kimi-k3.1-pro , messages : [{ role : user , content : 北京今天天气怎么样？ }], tools : [ { type : function , function : { name : get_weather , description : 获取指定城市的天气 , parameters : { type : object , properties : { city : { type : string , description : 城市名称 } }, required : [ city ] } } } ] } 响应中的 tool_calls 当 finish_reason 为 tool_calls 时，模型返回 tool_calls 数组，包含 id 、 function.name 和 function.arguments ： { choices : [{ message : { role : assistant , content : , reasoning_content : 用户问北京今天天气。需要调用天气工具。工具只需 city。调用 get_weather 城市北京。然后基于结果回答。注意当前日期系统提供2026-04-25，但天气工具会返回指定城市天气（可能实时）。调用。 , tool_calls : [ { id : get_weather_0_995b2511 , type : function , function : { arguments : { \ city \ : \ 北京 \ } , name : get_weather } } ] }, finish_reason : tool_calls }] } 提交工具执行结果 在本地执行工具后，先将响应中的完整 assistant message（包括 reasoning_content 和 tool_calls ）原样追加到原请求的 messages ，再追加以下工具结果； tool_call_id 必须与 assistant 消息中的工具调用 id 对应： { role : tool , tool_call_id : get_weather_0_995b2511 , content : 晴，25°C } 详见 使用 Kimi API 完成工具调用 。 思考模式与 Preserved Thinking Kimi K3 系列始终开启思考与 Preserved Thinking，使用顶层 reasoning_effort （支持 low 、 high 、 max ，默认 max ），不使用 thinking 参数。 Kimi K2.6 和 Kimi K2.7 Code 请求参数 参数 kimi-k2.6 kimi-k2.7-code 和 kimi-k2.7-code-highspeed thinking.type 默认 enabled ，传 disabled 可关闭思考。 仅支持 enabled ，传 disabled 会报错。 thinking.keep 默认 null ，不保留历史轮次的 reasoning_content 。传 all 启用保留式思考（Preserved Thinking）。 省略、传 null 或传 all 均按 all 处理，始终保留历史轮次的 reasoning_content 。传入其他值会报错。 响应字段 非流式响应中， choices[0].message 包含： 字段 说明 content 最终答案 reasoning_content 推理过程（仅在思考模式启用时返回） { choices : [{ message : { role : assistant , content : 1 + 1 = 2 , reasoning_content : The user is asking a simple math question in Chinese: \ 1+1 等于多少？ \ (What is 1+1?) 

 This is a trivial arithmetic question. The answer is 2. I should respond in Chinese since the conversation is in Chinese. Keep it simple and direct. } }] } 启用保留式思考时，请将历史 assistant 消息的 reasoning_content 原样回传到 messages ，以保留推理上下文。 详见 配置思考模式 。 流式输出 Streaming 设置 stream: true 可启用流式输出，模型会以 Server-Sent Events (SSE) 格式逐段返回生成的内容。推荐在聊天、代码生成、长文本输出等实时性要求高的场景中使用。 completion = client.chat.completions.create( model = kimi-k3.1-pro , messages = [{ role : user , content : 请解释什么是递归。 }], stream = True , stream_options = { include_usage : True }, ) for chunk in completion: if chunk.usage is not None : print ( 
 usage: , chunk.usage.model_dump()) if not chunk.choices: continue delta = chunk.choices[ 0 ].delta reasoning: str = getattr (delta, reasoning_content , None ) or if reasoning: print (reasoning, end = ) if delta.content: print (delta.content, end = ) SSE 响应格式 每一行以 data: 开头，内容为 JSON 对象。先接收 delta.reasoning_content ，再接收 delta.content ； finish_reason= stop 表示生成结束，其后的统计块 choices 为空，需从顶层 usage 读取用量： data: { id : chatcmpl-6adb0efa76cd871ffe47cb4d , object : chat.completion.chunk , created :1792741114, model : kimi-k3.1-pro , choices :[{ index :0, delta :{ role : assistant , content : }, finish_reason :null}], system_fingerprint : fpv0_6e24f0d2 } data: { id : chatcmpl-6adb0efa76cd871ffe47cb4d , object : chat.completion.chunk , created :1792741114, model : kimi-k3.1-pro , choices :[{ index :0, delta :{ reasoning_content : The }, finish_reason :null}], system_fingerprint : fpv0_6e24f0d2 } ... data: { id : chatcmpl-6adb0efa76cd871ffe47cb4d , object : chat.completion.chunk , created :1792741114, model : kimi-k3.1-pro , choices :[{ index :0, delta :{ content : # }, finish_reason :null}], system_fingerprint : fpv0_6e24f0d2 } ... data: { id : chatcmpl-6adb0efa76cd871ffe47cb4d , object : chat.completion.chunk , created :1792741114, model : kimi-k3.1-pro , choices :[], usage :{ prompt_tokens :90, completion_tokens :1139, total_tokens :1229, completion_tokens_details :{ reasoning_tokens :620}, prompt_tokens_details :{ cache_write_tokens :0}}} data: [DONE] stream_options 通过 stream_options: { include_usage : true} 可在最后一个 chunk（ data: [DONE] 之前）额外获取 usage 字段，显示本次请求的 Token 消耗： stream = True , stream_options = { include_usage : True } 详见 利用 Kimi API 的流式输出功能 。 Partial Mode Partial Mode（Prefill）允许你在 messages 的最后一条 assistant 消息中预填输出前缀，从而引导模型按照你期望的格式或方向继续生成。 开启方式 在 messages 数组末尾添加一条 role= assistant 的消息，并设置 partial: true ： completion = client.chat.completions.create( model = kimi-k3.1-pro , messages = [ { role : user , content : 用 Python 实现快速排序。 }, { role : assistant , content : ```python 
